(function(){const b=document.body,mb=document.getElementById("mb"),sc=document.getElementById("scrim"),nv=document.getElementById("nav");
 const set=o=>{b.classList.toggle("navopen",o);mb.setAttribute("aria-expanded",String(o));mb.setAttribute("aria-label",o?"ปิดเมนู":"เปิดเมนู")};
 mb.onclick=()=>set(!b.classList.contains("navopen"));sc.onclick=()=>set(false);
 nv.addEventListener("click",e=>{if(e.target.closest("button"))set(false)});
 document.addEventListener("keydown",e=>{if(e.key=="Escape")set(false)});
 window.matchMedia("(min-width:1025px)").addEventListener("change",e=>{if(e.matches)set(false)})})();
